n = len(arr)
dp = [[float('inf')] * n for _ in range(n)]

# Initialize the diagonal elements as 0 since no changes are needed there.
for i in range(n):
    dp[i][i] = 0

# Fill the table using bottom-up dynamic programming approach.
for length in range(2, n + 1):
    for start in range(n - length + 1):
        end = start + length - 1
        if length == 2:
            dp[start][end] = abs(arr[start] - arr[end])
        else:
            min_changes = float('inf')
            for mid in range(start + 1, end):
                min_changes = min(min_changes, 
                                  dp[start][mid] + dp[mid][end] + abs(arr[start] - arr[mid]))
            dp[start][end] = min_changes

return dp[0][n-1]

